12	class AudioPlayer {
13	  private readonly audioContext: AudioContext;
14	  private sourceNode: AudioBufferSourceNode | null = null;
15	  private audioBuffer: AudioBuffer | null = null;
16	  private volumeNode: GainNode | null = null;
17	
18	  private isPlaying: boolean = false;
19	
20	  private currentElapsedTime: number = 0;
21	  private playbackRate: number = 1;
22	  private volume: number = 1;
23	  private onPositionChanged: ((offset: number) => void) | null = null;
24	
25	  constructor() {
26	    this.audioContext = new AudioContext();
27	  }
28	
29	  play = async () => {
30	    if (this.isPlaying) {
31	      console.warn('Audio is already playing');
32	      return;
33	    }
34	
35	    if (!this.audioBuffer) {
36	      console.warn('Audio buffer is not loaded');
37	      return;
38	    }
39	
40	    this.isPlaying = true;
41	    PlaybackNotificationManager.show({
42	      state: 'playing',
43	    });
44	
45	    if (this.audioContext.state === 'suspended') {
46	      await this.audioContext.resume();
47	    }
48	
49	    this.sourceNode = this.audioContext.createBufferSource({pitchCorrection: true});
50	    this.sourceNode.buffer = this.audioBuffer;
51	    this.sourceNode.playbackRate.value = this.playbackRate;
52	    this.volumeNode = this.audioContext.createGain();
53	    this.volumeNode.gain.value = this.volume;
54	
55	    this.sourceNode.connect(this.volumeNode).connect(this.audioContext.destination);
56	    this.sourceNode.onPositionChangedInterval = 1000;
57	    this.sourceNode.onPositionChanged = (event) => {
58	      PlaybackNotificationManager.show({
59	        elapsedTime: this.currentElapsedTime,
60	      });
61	      this.currentElapsedTime = event.value;
62	      if (this.onPositionChanged) {
63	        this.onPositionChanged(
64	          this.currentElapsedTime / this.audioBuffer!.duration
65	        );
66	      }
67	    };
68	
69	    this.sourceNode.start(
70	      this.audioContext.currentTime,
71	      this.currentElapsedTime
72	    );
73	  };
74	
75	  pause = async () => {
76	    if (!this.isPlaying) {
77	      console.warn('Audio is not playing');
78	      return;
79	    }
80	
81	    this.sourceNode?.stop(this.audioContext.currentTime);
82	
83	    await this.audioContext.suspend();
84	    PlaybackNotificationManager.show({
85	      state: 'paused',
86	      elapsedTime: this.currentElapsedTime,
87	    });
88	
89	    this.isPlaying = false;
90	  };
91	
92	  seekBy = (seconds: number) => {
93	    this.sourceNode?.stop(this.audioContext.currentTime);
94	    this.currentElapsedTime += seconds;
95	    if (this.currentElapsedTime < 0) {
96	      this.currentElapsedTime = 0;
97	    } else if (this.currentElapsedTime > this.getDuration()) {
98	      this.currentElapsedTime = this.getDuration();
99	    }
100	    PlaybackNotificationManager.show({
101	      elapsedTime: this.currentElapsedTime,
102	    });
103	
104	    if (this.isPlaying) {
105	      this.isPlaying = false;
106	      this.play();
107	    }
108	  };
109	
110	  loadBuffer = async (asset: string | number) => {
111	    const buffer = await this.audioContext.decodeAudioData(asset);
112	
113	    if (buffer) {
114	      this.audioBuffer = buffer;
115	      this.playbackRate = 1;
116	    }
117	  };
118	
119	  reset = async () => {
120	    if (this.sourceNode) {
121	      this.sourceNode.onEnded = null;
122	      this.sourceNode.onPositionChanged = null;
123	      this.sourceNode.stop(this.audioContext.currentTime);
124	    }
125	    this.audioBuffer = null;
126	    this.sourceNode = null;
127	    this.currentElapsedTime = 0;
128	    this.playbackRate = 1;
129	    this.isPlaying = false;
130	
131	    await this.audioContext.suspend();
132	  };
133	
134	  setOnPositionChanged = (
135	    callback: null | ((offset: number) => void) = null
136	  ) => {
137	    this.onPositionChanged = callback;
138	  };
139	
140	  getDuration = (): number => {
141	    return this.audioBuffer?.duration ?? 0;
142	  };
143	
144	  getElapsedTime = (): number => {
145	    return this.currentElapsedTime;
146	  };
147	
