44	        );
45	        return;
46	      }
47	
48	      await AudioPlayer.play();
49	
50	      AudioManager.observeAudioInterruptions(true);
51	
52	      AudioManager.getDevicesInfo().then(console.log);
53	    }
54	
55	    setIsPlaying((prev) => !prev);
56	  };
57	
