67	    try {
68	      await AudioManager.requestNotificationPermissions();
69	      const duration = AudioPlayer.getDuration();
70	      await PlaybackNotificationManager.show({
71	        title: 'Audio File',
72	        artist: 'Software Mansion',
73	        album: 'Audio API',
74	        duration: duration,
75	        state: 'paused',
76	        speed: 1.0,
77	        elapsedTime: 0,
78	      });
79	      await PlaybackNotificationManager.enableControl('skipBackward', true);
80	      await PlaybackNotificationManager.enableControl('nextTrack', true);
81	      await PlaybackNotificationManager.enableControl('skipForward', true);
82	      await PlaybackNotificationManager.enableControl('previousTrack', true);
83	      await PlaybackNotificationManager.enableControl('pause', true);
84	      await PlaybackNotificationManager.enableControl('play', true);
85	      await PlaybackNotificationManager.enableControl('seekTo', true);
86	
87	    } catch (error) {
88	      console.error('Failed to setup notification:', error);
89	    }
90	  };
91	
92	  useEffect(() => {
93	    const setup = async () => {
94	      await fetchAudioBuffer();
95	      await setupNotification();
96	    };
97	    setup();
98	    return () => {
99	      AudioPlayer.reset();
100	      PlaybackNotificationManager.hide();
101	      AudioManager.setAudioSessionActivity(false);
102	    };
103	  }, [fetchAudioBuffer]);
104	
105	  useEffect(() => {
106	    AudioManager.observeAudioInterruptions(true);
107	
108	    // Listen to notification control events
109	    const playListener = PlaybackNotificationManager.addEventListener(
110	      'playbackNotificationPlay',
111	      () => {
112	        AudioPlayer.play();
113	        setIsPlaying(true);
114	      }
115	    );
116	
117	    const pauseListener = PlaybackNotificationManager.addEventListener(
118	      'playbackNotificationPause',
119	      () => {
120	        AudioPlayer.pause();
121	        setIsPlaying(false);
122	      }
123	    );
124	
125	    const skipForwardListener = PlaybackNotificationManager.addEventListener(
126	      'playbackNotificationSkipForward',
127	      (event) => {
128	        AudioPlayer.seekBy(event.value);
129	      }
130	    );
131	
132	    const skipBackwardListener = PlaybackNotificationManager.addEventListener(
133	      'playbackNotificationSkipBackward',
134	      (event) => {
135	        AudioPlayer.seekBy(-event.value);
136	      }
137	    );
138	
139	    // Keep interruption handling through AudioManager
140	    const interruptionSubscription = AudioManager.addSystemEventListener(
141	      'interruption',
142	      async (event) => {
143	        if (event.type === 'began' && isPlaying) {
144	          await AudioPlayer.pause();
145	          setIsPlaying(false);
146	          setWasPlaying(true);
147	          return;
148	        }
149	
150	        if (event.type === 'ended' && wasPlaying) {
151	          BackgroundTimer.setTimeout(async () => {
152	            AudioPlayer.setVolume(1.0);
153	            AudioManager.setAudioSessionActivity(true);
154	            await AudioPlayer.play();
155	            setIsPlaying(true);
156	            setWasPlaying(false);
157	            console.log('Auto-resumed after transient interruption');
158	          }, 500);
159	        }
160	      }
161	    );
162	
163	    const duckListener = AudioManager.addSystemEventListener(
164	      'duck',
165	      () => {
166	        AudioPlayer.setVolume(0.2);
167	      }
168	    );
169	
170	    const seekToListener = PlaybackNotificationManager.addEventListener(
171	      'playbackNotificationSeekTo',
172	      (event) => {
173	        AudioPlayer.seekBy(event.value - AudioPlayer.getElapsedTime());
174	      }
175	    );
176	
177	    return () => {
178	      playListener.remove();
179	      pauseListener.remove();
180	      skipForwardListener.remove();
181	      skipBackwardListener.remove();
182	      seekToListener.remove();
183	      interruptionSubscription?.remove();
184	      duckListener.remove();
185	    };
186	  }, [isPlaying, wasPlaying]);
187	
188	  return (
189	    <Container centered>
190	      {isLoading && <ActivityIndicator color="#FFFFFF" />}
191	      <Button
192	        title={isPlaying ? 'Stop' : 'Play'}
193	        onPress={togglePlayPause}
194	        disabled={isLoading}
195	      />
196	      <Spacer.Vertical size={20} />
197	      <View style={styles.progressContainer}>
198	        <View
199	          style={[
200	            styles.progressBar,
201	            { width: `${positionPercentage * 100}%` },
202	          ]}
203	        />
204	      </View>
205	    </Container>
206	  );
207	};
208	
209	export default AudioFile;
