216	    borderRadius: 5,
217	    overflow: 'hidden',
218	    marginTop: 20,
219	  },
220	  progressBar: {
221	    height: '100%',
222	    backgroundColor: colors.main,
223	    borderRadius: 5,
224	  },
225	});
